<?php /** @var array $refunds */ ?><!doctype html><html><head><meta charset="utf-8"><title>Refunds</title><style>body{font-family:system-ui;margin:32px;max-width:1100px}.card{border:1px solid #ddd;border-radius:10px;padding:20px;margin-bottom:20px}input,textarea,button{padding:9px;margin:4px 0;box-sizing:border-box}input,textarea{width:100%}button{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><h1>Payment Refunds</h1><div class="card"><h2>Request refund</h2><form method="post" action="/finance/refunds/request"><label>Payment ID</label><input type="number" name="payment_id" required><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required><label>Reason</label><textarea name="reason" required></textarea><label>Reference</label><input name="reference"><button type="submit">Request Refund</button></form></div><div class="card"><h2>Refund history</h2><table><tr><th>Student</th><th>Receipt</th><th>Amount</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php foreach($refunds as $r):?><tr><td><?=htmlspecialchars($r['admission_no'].' - '.$r['first_name'].' '.$r['last_name'])?></td><td><?=htmlspecialchars($r['receipt_no'])?></td><td>KES <?=number_format((float)$r['amount'],2)?></td><td><?=htmlspecialchars($r['reason'])?></td><td><?=htmlspecialchars(ucfirst($r['status']))?></td><td><?php if($r['status']==='requested'):?><form method="post" action="/finance/refunds/approve"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Approve</button></form><?php elseif($r['status']==='approved'):?><form method="post" action="/finance/refunds/process"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Mark Processed</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></body></html>
